{"command": "python3 - << 'EOF'
import json, subprocess

def ft2(tool, args):
    r = subprocess.run(["ft2","call",tool,json.dumps(args)],capture_output=True,text=True)
    return r.stdout.strip()

def batch(cmds):
    with open('/tmp/bfin.json','w') as f: json.dump(cmds,f)
    r = subprocess.run(["ft2","batch","/tmp/bfin.json"],capture_output=True,text=True)
    if r.returncode: print("ERR:",r.stderr[-200:])

def N(name,oct):
    s={'C':0,'Cs':1,'D':2,'Ds':3,'E':4,'F':5,'Fs':6,'G':7,'Gs':8,'A':9,'As':10,'B':11}
    return oct*12+s[name]+1

def PC(pat,row,ch,note=None,inst=None,vol=None,eff=None,ep=None):
    a={'pattern':pat,'row':row,'channel':ch}
    if note is not None: a['note']=note
    if inst is not None: a['instrument']=inst
    if vol  is not None: a['volume']=vol
    if eff  is not None: a['effect']=eff
    if ep   is not None: a['effect_param']=ep
    return {"name":"pattern_set_cell","arguments":a}

KEYOFF=97
E5=N('E',5); G5=N('G',5); B5=N('B',5)
Ds5=N('Ds',5); Fs5=N('Fs',5)
E4=N('E',4); G4=N('G',4); B4=N('B',4)
A4=N('A',4); C5=N('C',5)
ARP,BASS,KICK,SNARE,HIHAT=7,4,1,2,3

cmds=[]
# Pattern 4: dramatic drum fill in final B section (rows 56-62)
for r in [58, 60, 62]:
    cmds.append(PC(4, r, 0, C5, KICK, vol=54))
cmds.append(PC(4, 60, 1, C5, SNARE, vol=50))

# Pattern 4: B section chord voice more active
for r,n in [(48,B4),(50,B4),(52,Ds5),(54,Ds5),(56,Fs5),(58,Fs5),(60,B5),(62,B5)]:
    cmds.append(PC(4, r, 7, note=n, inst=ARP, vol=42))

# Pattern 4 Em section: add descending counter on ch7 off-beats
for r,n in [(2,B5),(6,G5),(10,E5),(14,B4)]:
    cmds.append(PC(4, r, 7, note=n, inst=ARP, vol=35))

# Pattern 2 Am section: richer chords on ch7
for r,n in [(16,A4),(18,C5),(20,E5),(22,A4),(24,C5),(26,E5),(28,A4),(30,C5)]:
    cmds.append(PC(2, r, 7, note=n, inst=ARP, vol=36))

batch(cmds)
print(f"Added {len(cmds)} refinements")

ft2("module_save", {"path": "/workspace/submission/tune.xm", "format": "xm"})
ft2("module_render", {"path": "/workspace/submission/preview.wav", "rate": 44100, "loops": 2})
print("Done")
EOF"}

